<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Core / DX</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f6f7fb;color:#172033}.card{border:0;box-shadow:0 .3rem 1rem rgba(0,0,0,.06)}pre{background:#111827;color:#e5e7eb;padding:14px;border-radius:10px;white-space:pre-wrap}.ok{color:#198754}.bad{color:#dc3545}.badge-live{background:#fff3cd;color:#7a5b00}</style></head><body><div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Core / DX</h1><div class="text-secondary">ScratchByPHP v0.8.5 test paneli</div></div><a href="index.php" class="btn btn-outline-secondary">← Paneller</a></div><?php
use ScratchByPHP\Scratch;use ScratchByPHP\Collections\Collection;use ScratchByPHP\Cache\MemoryCache;use ScratchByPHP\DTO\ProjectStats;
$out=[];try{$s=new Scratch(['timeout'=>12,'retries'=>2]);$out['version']=Scratch::version();$out['health_local']=$s->healthCheck(false);$out['collection']=(new Collection([5,1,3,2]))->filter(fn($x)=>$x>1)->sortBy(fn($x)=>$x)->take(3)->all();$c=new MemoryCache();$c->set('demo',['ok'=>true]);$out['cache']=$c->get('demo');$out['dto']=(new ProjectStats(100,5,3,1))->toArray();$fake=Scratch::fake()->fakeProject(7,['title'=>'Fake demo','stats'=>['views'=>77]]);$out['fake']=['title'=>$fake->project(7)->title(),'views'=>$fake->project(7)->views()];}catch(Throwable $e){$out=['error'=>$e->getMessage()];}?><div class="card"><div class="card-body"><pre><?=htmlspecialchars(json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></div></div></div></body></html>